// on start: runs once when the micro:bit turns on
basic.showString("Hi")

// forever: runs over and over until the power is removed
basic.forever(function () {
    basic.showIcon(IconNames.Heart)
})

basic.forever(function () {
    basic.showString("Hello Mr Butler")
})

input.onButtonPressed(Button.A, function () {
    basic.showString("Hello Mr Butler!")
})

let myValue = 0
while (myValue < 10) {
    basic.showNumber(myValue)
    myValue += 1
}

basic.forever(function () {
    for (let index = 0; index < 3; index++) {
        basic.showNumber(0)
        basic.showNumber(1)
        basic.showNumber(2)
        basic.showNumber(3)
    }
    basic.showNumber(4)
    basic.showNumber(5)
    basic.showNumber(6)
})

input.onGesture(Gesture.Shake, function () {
    basic.showNumber(randint(1, 6))
})

let roll = 0
input.onGesture(Gesture.Shake, function () {
    roll = randint(1, 6)
    basic.showNumber(roll)
})

input.onButtonPressed(Button.A, function () {
    if (Math.randomBoolean()) {
        basic.showString("It's True!")
    } else {
        basic.showString("It's False!")
    }
})

basic.forever(function () {
    let a = 0
    let b = 0
    if (input.buttonIsPressed(Button.A)) {
        a = 1
    }
    if (input.buttonIsPressed(Button.B)) {
        b = 1
    }
    if (a == 1 && b < 1) {
        basic.showIcon(IconNames.Happy)
    } else if (a == 1 && b == 1) {
        basic.showIcon(IconNames.Sad)
    } else if (a != 1 && b == 1) {
        basic.showIcon(IconNames.Meh)
    } else {
        basic.clearScreen()
    }
})

let myValue = 5
if (myValue < 10 && myValue > 0) {
    basic.showIcon(IconNames.Yes)
}

let myValue = 15
if (myValue > 10 || myValue < 0) {
    basic.showIcon(IconNames.Yes)
}

let myValue = false
if (!(myValue)) {
    basic.showIcon(IconNames.Yes)
}

basic.forever(function () {
    if (input.buttonIsPressed(Button.A) || input.buttonIsPressed(Button.B)) {
        basic.showString("T")
    } else {
        basic.showString("F")
    }
})

basic.forever(function () {
    if (!(input.buttonIsPressed(Button.A))) {
        basic.showNumber(1)
    } else {
        basic.showNumber(0)
    }
})
